import numpy as np
from scipy.optimize import minimize
import os

N = 26

def construct_packing() -> tuple:
    # --- Helper for structured seed ---
    def generate_grid_hole_seed(hole_pos_idx):
        coords = [0.1, 0.3, 0.5, 0.7, 0.9]
        grid_centers = np.array([[x, y] for x in coords for y in coords])
        row_idx, col_idx = hole_pos_idx//5, hole_pos_idx%5
        hole_center = np.array([0.2 + row_idx*0.2, 0.2 + col_idx*0.2])
        return np.vstack([grid_centers, hole_center])

    # --- Helper functions for SLSQP ---
    def cr_to_z(c, r): return np.concatenate([c.flatten(), r])
    def z_to_cr(z): return z[:N*2].reshape(N, 2), z[N*2:]
    def objective(z): return -np.sum(z[N*2:])
    def ineq_boundary(z):
        c, r = z_to_cr(z)
        return np.concatenate([c[:,0] - r, 1 - (c[:,0] + r), c[:,1] - r, 1 - (c[:,1] + r)])
    def ineq_nonoverlap(z):
        c, r = z_to_cr(z)
        diff = c[:, None, :] - c[None, :, :]; dist = np.sqrt(np.sum(diff**2, axis=-1))
        iu = np.triu_indices(N, 1); return dist[iu] - (r[iu[0]] + r[iu[1]])
    def _ensure_validity(c, r):
        for _ in range(10):
            v=0
            for i in range(N):
                for j in range(i + 1, N):
                    dist = np.linalg.norm(c[i] - c[j]); rad_sum = r[i] + r[j]
                    if dist < rad_sum: v+=1; scale = (dist/rad_sum)*(1.0-1e-9); r[i]*=scale; r[j]*=scale
            if v==0: break
        return c, np.maximum(r, 0)

    # --- Main Multi-Start Loop ---
    best_overall_score = -np.inf
    best_overall_packing = (None, None)
    num_starts = 5 # Run on 5 different grid-hole seeds

    for start_idx in range(num_starts):
        # --- Stage 1: Physics Simulation with Structured Seed ---
        sim_iters = 40000
        dt = 1e-4; k_repulsion = 20.0; damping = 0.98; fixed_radius = 0.1

        centers = generate_grid_hole_seed(start_idx)
        radii = np.full(N, fixed_radius)
        velocities = np.zeros((N, 2))

        for _ in range(sim_iters):
            forces = np.zeros((N, 2))
            radii_sum = 2 * fixed_radius
            for i in range(N):
                for j in range(i + 1, N):
                    delta = centers[j] - centers[i]
                    dist_sq = np.sum(delta**2)
                    if dist_sq < radii_sum**2 and dist_sq > 1e-12:
                        dist = np.sqrt(dist_sq); overlap = radii_sum - dist
                        direction = delta / dist; force_magnitude = k_repulsion * overlap
                        forces[i] -= force_magnitude * direction; forces[j] += force_magnitude * direction
            for i in range(N): # Boundary repulsion
                if centers[i, 0] < fixed_radius: forces[i, 0] += k_repulsion * (fixed_radius - centers[i, 0])
                if centers[i, 0] > 1.0 - fixed_radius: forces[i, 0] -= k_repulsion * (centers[i, 0] - (1.0 - fixed_radius))
                if centers[i, 1] < fixed_radius: forces[i, 1] += k_repulsion * (fixed_radius - centers[i, 1])
                if centers[i, 1] > 1.0 - fixed_radius: forces[i, 1] -= k_repulsion * (centers[i, 1] - (1.0 - fixed_radius))

            velocities += forces * dt; velocities *= damping; centers += velocities * dt
            radii_vec = radii.reshape(-1, 1); centers = np.clip(centers, radii_vec, 1.0 - radii_vec)

        phys_seed_centers = centers
        phys_seed_radii = np.full(N, 0.05)

        # --- Stage 2: SLSQP Refinement ---
        initial_z = cr_to_z(phys_seed_centers, phys_seed_radii)
        bounds = [(0,1)]*N*2 + [(1e-6, 0.5)]*N
        constraints = [{'type': 'ineq', 'fun': ineq_boundary}, {'type': 'ineq', 'fun': ineq_nonoverlap}]

        res = minimize(objective, initial_z, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 1500, 'ftol': 1e-10})

        if res.success:
            c_res, r_res = z_to_cr(res.x)
            c_final, r_final = _ensure_validity(c_res, r_res)
            current_score = np.sum(r_final)
            if current_score > best_overall_score:
                best_overall_score = current_score
                best_overall_packing = (c_final, r_final)

    if best_overall_packing[0] is None:
        # Fallback
        return generate_grid_hole_seed(0), np.full(N, 0.05)

    return best_overall_packing
